#!/usr/bin/env python3
# luxarch:no-self-park hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""An agent does not park its own work: it works it, closes it, or asks the owner one question.

PreToolUse(mcp__luxpm__luxpm_update_issue, mcp__luxpm__luxpm_create_issue, mcp__luxpm__luxpm_chat,
and the LuxPM delete, page and memory writes).
Each issue the call changes (the single form and each `updates[]` entry; a create) is judged on the
state it sets, compared lower-cased. An agent sets only:

- `todo`, `in_progress`, or `done` (a close, which `luxpm-close-tracks-deferrals` reads);
- `on_hold` with `waiting_on` that is, whole, `owner: <the question?>`: the one question the owner
  answers, and the agent waits on the answer.

Every other state is denied: `backlog`, `cancelled` (a cancel is the owner's call, asked as one
question), and `on_hold` waiting on anyone or anything else. `todo` on an issue LuxPM shows
`in_progress` puts the work down, and is denied too. A create with no `state` is filed by LuxPM as
`backlog`, and is judged as one: an escalation is filed `todo`.

`waiting_on` is judged on every update that sets it, with or without a state: it names whoever
acts next. It passes as `owner: <the question?>`; on an escalation (labelled `fleet-escalation`,
`escalation` or `escalation-from-<project>`, or titled `[… ESCALATION] …` or `[<KEY>] …`), also as
`<guard> maintainer[: …]` (or `<guard>/<guard> maintainer` for one filed against two guards)
when this repo filed it and no guard named is this repo. From a guard's
own repo it also passes as `<guard> maintainer: …` on another project's escalation (queued on
this guard, or handed to the guard it belongs to) or on one relayed into this guard's project
(queued here), and as `<repo> agent: …` (the reporting repo's step) on another project's.
On an issue of this repo's project it also passes as `<role> agent: <step>`, a handoff to
another agent of this repo: the role and this session's own (from the name the owner gave it)
both declared in the committed `.luxarch.toml` (`[agents] roles`), and different.
Clearing it passes only as the issue is, or is set, `todo`, `in_progress` or `done`.

The `owner-order` label is the owner's: an update whose `labels` add it or drop it is denied, and
so is a create carrying it. An escalation's labels (`fleet-escalation`, `escalation`,
`escalation-from-<project>`) are set when it is filed: an update that adds or drops one is denied.
Re-sending the labels an issue already has passes. An owner order's `title` and `description` are
the owner's words, and an update that rewrites either is denied.

What an issue is (its state, labels, title and waiting_on) is read from LuxPM itself when the hook
judges it (`_ledger.luxpm_issues`: one `luxpm_get_context` call to LuxPM's MCP endpoint, with the
connection Claude Code uses for LuxPM in this project), never from the session's transcript. An
update that sets a state other than `done`, or `labels`, `waiting_on`, `title` or `description`,
is denied while LuxPM cannot be read, and on an issue LuxPM does not know (a project named by its
UUID with a bare number is not a key: name the project by its code).

A `luxpm_chat` query is natural language LuxPM may turn into any change, and is denied outright.
So are `luxpm_delete_issue` and `luxpm_delete_page` (a delete is the owner's call) and the page
and memory writes (`luxpm_create_page`, `update_page`, `patch_page`, `generate_page`,
`store_memory`, `update_memory`), `luxpm_upsert_adr` and `luxpm_update_project`: no fleet
skill writes them, and work put there is in no issue.

A state that needs no issue to judge (`backlog`, `cancelled`, an `on_hold` with no owner question)
is denied before LuxPM is asked, so a call already denied waits on nothing. From a guard's own
repo, the maintainer may add an escalation label to another project's issue its triage found
unlabelled, and may hand an escalation relayed into its project (`escalation-from-<x>`) back to
`<x> agent: …`.

Work found and not done is worked, escalated to another repo's guard, or asked of the owner as one
question (FLEET-AGENT-CONDUCT-STANDARD, "Work what you find; never defer it"). A call it cannot
read changes nothing it can judge, and passes.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _ledger import (
    GUARDS,
    HANDOFF_LABEL,
    OWNER_ORDER_LABEL,
    OWNER_QUESTION_FORM,
    Issue,
    LuxPMUnread,
    agent_name,
    agent_role,
    declared_roles,
    handoff_to,
    is_escalation,
    luxpm_issues,
    owner_question,
    read_event,
    repo_project,
    role_name,
    row_labels,
    tree_dir,
)

_UPDATE = "mcp__luxpm__luxpm_update_issue"
_CREATE = "mcp__luxpm__luxpm_create_issue"
_CHAT = "mcp__luxpm__luxpm_chat"
# no fleet skill writes these; each is a place outside every issue to put work, or a removal
_OWNERS_TOOLS = {
    "mcp__luxpm__luxpm_delete_issue": "deleting an issue is the owner's call",
    "mcp__luxpm__luxpm_delete_page": "deleting a page is the owner's call",
    "mcp__luxpm__luxpm_create_page": "a page is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_update_page": "a page is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_patch_page": "a page is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_generate_page": "a page is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_store_memory": "a memory is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_update_memory": "a memory is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_upsert_adr": "an ADR is no place for work: it lives in its issue",
    "mcp__luxpm__luxpm_update_project": "a project's description is no place for work",
}
_UNKNOWN = (
    "LuxPM knows no such issue (name it by its key, `AB-12`, or its number with the project's "
    "code), so what it is cannot be read"
)
_WORKED = ("todo", "in_progress", "done")
_CLEARED = ("", "null", "none")
# `<guard> maintainer[: …]`, or `<guard>/<guard> maintainer` for one escalation to two guards
_GUARD_WAIT = re.compile(
    r"(?P<g>[a-z]+(?:/[a-z]+)*) maintainer(?::\s*\S.*)?", re.DOTALL
)
# `<repo> agent: <step>`: the repo's name as the owner writes it (`shop-api agent: …`)
_AGENT_WAIT = re.compile(
    r"(?P<p>[A-Za-z0-9][A-Za-z0-9._-]{0,40}) agent:\s*\S.*", re.DOTALL
)
_GUARD_PROJECTS = tuple(g.upper() for g in GUARDS)
_HANDOFF_NAMED = re.compile(r"(?P<role>[A-Za-z0-9][A-Za-z0-9 _-]{0,40}?) agent:")


def _entries(inp: dict[str, object]) -> list[dict[str, object]]:
    out = [inp]
    updates = inp.get("updates")
    if isinstance(updates, list):
        out += [u for u in updates if isinstance(u, dict)]
    return out


def _key(entry: dict[str, object], project: object) -> str:
    seq = str(entry.get("sequence_id") or "").strip().upper()
    if "-" in seq or not seq:
        return seq
    proj = str(entry.get("project") or project or "").strip().upper()
    return f"{proj}-{seq}" if proj else seq


def _label_list(raw: object) -> list[str] | None:
    if isinstance(raw, str):
        return [x.strip().lower() for x in raw.split(",") if x.strip()]
    if isinstance(raw, list):
        return [str(x).strip().lower() for x in raw]
    return None


_row_labels = row_labels
_escalation = is_escalation


def _state_fault(state: str, waiting: object, row: Issue | None, create: bool) -> str:
    if state == "on_hold" and not owner_question(waiting):
        return f"on_hold waits only on a question to the owner, {OWNER_QUESTION_FORM}"
    if state not in ("on_hold", *_WORKED):
        if state == "cancelled":
            return "a cancel is the owner's call: ask the owner one question"
        return (
            f"an agent sets todo, in_progress, done, or on_hold with {OWNER_QUESTION_FORM}; "
            f"`{state}` sets the work aside"
        )
    if not create and row is None and state != "done":
        return _UNKNOWN
    if state == "on_hold":
        return ""
    if (
        state == "todo"
        and not create
        and row
        and str(row.get("state")) == "in_progress"
    ):
        return "it is in progress: moving it back to todo puts the work down"
    if state in _WORKED:
        return ""
    if state == "cancelled":
        return "a cancel is the owner's call: ask the owner one question"
    return (
        f"an agent sets todo, in_progress, done, or on_hold with {OWNER_QUESTION_FORM}; "
        f"`{state}` sets the work aside"
    )


def _waiting_fault(
    entry: dict[str, object],
    key: str,
    row: Issue | None,
    own: str,
    create: bool,
    handoff: tuple[str, list[str]] = ("", []),
) -> str:
    """`waiting_on`, set with or without a state, names whoever acts next: the owner (a question),
    or on an escalation, the guard maintainer it waits on or the agent whose step is next."""
    text = str(entry.get("waiting_on") or "").strip()
    state = str(entry.get("state") or "").strip().lower()
    if text.lower() in _CLEARED:
        now = state or (str(row.get("state")) if row else "")
        if now in _WORKED:
            return ""
        return (
            "clearing waiting_on leaves the issue waiting on no one: clear it as you set it to "
            "todo, in_progress or done"
        )
    if owner_question(text):
        return ""
    sent = _label_list(entry.get("labels"))
    after = sent if sent is not None else ([] if create else _row_labels(row))
    project_of = (
        str(entry.get("project") or own).strip().upper()
        if create
        else (key.rsplit("-", 1)[0] if "-" in key else "")
    )
    role = handoff_to(text, *handoff) if project_of == own else ""
    if role:
        if state in ("done", "cancelled"):
            return (
                "a close hands nothing off: an issue that still needs another agent's step "
                "stays open, labelled for it"
            )
        if f"{HANDOFF_LABEL}{role}" not in {_label_role(x) for x in after}:
            return (
                f"a handoff to the {role} agent carries `{HANDOFF_LABEL}{role}`, the label its "
                "/fleet-start lists: add it in the same call"
            )
        return ""  # handed to another declared agent of this repo
    if create:
        title, labels = entry.get("title"), _label_list(entry.get("labels")) or []
        project = str(entry.get("project") or own).strip().upper()
    else:
        title, labels = (row.get("title") if row else ""), after
        project = key.rsplit("-", 1)[0] if "-" in key else ""
    if not create and row is None:
        return _UNKNOWN
    if _escalation(title, labels) and project:
        g = _GUARD_WAIT.fullmatch(text)
        named = g.group("g").split("/") if g else []
        if named and all(x in GUARDS for x in named):
            guards = {x.upper() for x in named}
            # the reporter's escalation waits on other guards' maintainers; a guard's maintainer
            # queues an escalation on itself (another project's, or one relayed into its own) or
            # hands another project's to the guard it belongs to
            if (project == own and own not in guards) or (
                own in _GUARD_PROJECTS and (project != own or guards == {own})
            ):
                return ""
        a = _AGENT_WAIT.fullmatch(text)
        relayed_from = {
            x[len("escalation-from-") :]
            for x in labels
            if x.startswith("escalation-from-")
        }
        if (
            a
            and own in _GUARD_PROJECTS
            and (project != own or a.group("p").lower() in relayed_from)
        ):
            return (
                ""  # a guard's maintainer answers: the reporting repo's agent acts next
            )
    return (
        f"waiting_on {text[:80]!r} names no one who acts next: an agent waits only on "
        f"{OWNER_QUESTION_FORM}; an escalation also waits on `<guard> maintainer: …` (filed by "
        "this repo) or on `<repo> agent: …` (a guard maintainer's answer)"
    )


def _label_role(label: str) -> str:
    """`agent:<role>` with the role as `role_name` gives it; any other label as it is."""
    if label.startswith(HANDOFF_LABEL):
        return HANDOFF_LABEL + role_name(label[len(HANDOFF_LABEL) :])
    return label


def _label_fault(
    raw: object,
    row: Issue | None,
    create: bool,
    key: str = "",
    own: str = "",
    waiting_after: str = "",
) -> str:
    labels = _label_list(raw)
    if labels is None:
        return ""
    has = OWNER_ORDER_LABEL in labels
    if create:
        return "the owner-order label is the owner's to set" if has else ""
    if row is None:
        return _UNKNOWN
    had = OWNER_ORDER_LABEL in _row_labels(row)
    if has and not had:
        return "the owner-order label is the owner's to add"
    if had and not has:
        return "it drops the owner-order label, which only the owner removes"
    had_agents = {
        _label_role(x) for x in _row_labels(row) if x.startswith(HANDOFF_LABEL)
    }
    has_agents = {_label_role(x) for x in labels if x.startswith(HANDOFF_LABEL)}
    if had and had_agents != has_agents:
        return "it changes which agent an owner order is for: that is the owner's"
    waited = _HANDOFF_NAMED.match(waiting_after.strip())
    if waited:
        named = HANDOFF_LABEL + role_name(waited.group("role"))
        if named in had_agents and named not in has_agents:
            return (
                f"it drops `{named}` while waiting_on still names that agent: answer or "
                "close it first, then drop the label"
            )
    moved = sorted(
        {x for x in labels if _escalation_label(x)}
        ^ {x for x in _row_labels(row) if _escalation_label(x)}
    )
    triage = own in _GUARD_PROJECTS and key.rsplit("-", 1)[0] not in ("", own)
    if moved and triage and not (set(_row_labels(row)) - set(labels)):
        moved = []  # a guard's triage adds the escalation label another repo left off
    if moved:
        return (
            f"it adds or drops {', '.join(moved)}: an escalation is one when it is filed "
            "(/escalate), and a label added later makes any issue a place to park work"
        )
    return ""


def _escalation_label(label: str) -> bool:
    return label in ("fleet-escalation", "escalation") or label.startswith(
        "escalation-from-"
    )


def _order_text_fault(entry: dict[str, object], row: Issue | None) -> str:
    """An owner order's title and description are the owner's words."""
    changed = [f for f in ("title", "description") if entry.get(f) not in (None, "")]
    if not changed:
        return ""
    if row is None:
        return _UNKNOWN
    if OWNER_ORDER_LABEL in _row_labels(row):
        return (
            f"it rewrites the {' and '.join(changed)} of an owner order: the owner's words "
            "stay as written; record what you learned as a comment"
        )
    return ""


_JUDGED_FIELDS = ("labels", "waiting_on", "title", "description")


def _needs_row(entry: dict[str, object]) -> bool:
    state = str(entry.get("state") or "").strip().lower()
    return (state not in ("", "done")) or any(f in entry for f in _JUDGED_FIELDS)


def _faults(inp: dict[str, object], create: bool, transcript: str = "") -> list[str]:
    entries = [inp] if create else _entries(inp)
    keyed = [
        (
            "the new issue"
            if create
            else (_key(e, inp.get("project")) or "this issue"),
            e,
        )
        for e in entries
    ]
    rows: dict[str, Issue] = {}
    unread = ""
    wanted = [k for k, e in keyed if not create and "-" in k and _needs_row(e)]
    early = [
        f"{k} -> {st}: {fault}"
        for k, e in keyed
        if (st := str(e.get("state") or "").strip().lower())
        and (fault := _state_fault(st, e.get("waiting_on"), {"state": ""}, create))
    ]
    if early:
        return early
    if wanted:
        try:
            rows = luxpm_issues(wanted)
        except LuxPMUnread as exc:
            unread = (
                f"LuxPM could not be read ({exc}), and what the issue is decides whether this "
                "change sets work aside; retry once LuxPM answers"
            )
    own = repo_project(tree_dir()).upper()
    out: list[str] = []
    for key, e in keyed:
        row = rows.get(key)
        state = str(e.get("state") or "").strip().lower()
        if create and not state:
            state = "backlog"  # LuxPM files a create with no state as backlog
        handoff = (agent_role(agent_name(transcript)), declared_roles())
        waiting_fault = (
            _waiting_fault(e, key, row, own, create, handoff)
            if "waiting_on" in e and state != "on_hold"
            else ""
        )
        handing = (
            "waiting_on" in e
            and not waiting_fault
            and bool(handoff_to(e.get("waiting_on"), *handoff))
        )
        if state:
            fault = _state_fault(state, e.get("waiting_on"), row, create)
            if fault and not (handing and state == "todo" and row is not None):
                out.append(f"{key} -> {state}: {fault}")
        if waiting_fault:
            out.append(f"{key} waiting_on: {waiting_fault}")
        if "labels" in e:
            waiting_after = str(
                e.get("waiting_on")
                if "waiting_on" in e
                else (row.get("waiting") if row else "") or ""
            )
            fault = _label_fault(e.get("labels"), row, create, key, own, waiting_after)
            if fault:
                out.append(f"{key} labels: {fault}")
        if not create:
            fault = _order_text_fault(e, row)
            if fault:
                out.append(f"{key}: {fault}")
    # with LuxPM unread, a fault that needs the issue says why it is missing
    return [f.replace(_UNKNOWN, unread) for f in out] if unread else out


def main() -> int:
    ev = read_event()
    name = str(ev.get("tool_name") or "")
    ti = ev.get("tool_input")
    inp: dict[str, object] = ti if isinstance(ti, dict) else {}
    if name == _CHAT:
        faults = [
            "luxpm_chat turns words into any change, so it is not used: read with "
            "luxpm_list_issues, luxpm_get_context or luxpm_semantic_search, change with "
            "luxpm_update_issue"
        ]
    elif name in _OWNERS_TOOLS:
        faults = [f"{name.rsplit('__', 1)[-1]}: {_OWNERS_TOOLS[name]}; ask the owner"]
    elif name in (_UPDATE, _CREATE):
        faults = _faults(inp, name == _CREATE, str(ev.get("transcript_path") or ""))
    else:
        return 0
    if not faults:
        return 0
    print(
        "DENIED: an agent works its issues, closes them, or asks the owner one question.\n"
        + "".join(f"  - {f}\n" for f in faults)
        + "Work it: a finding in the work at hand is fixed in that change. A defect in another\n"
        "repo's guard is /escalate-d. When it is the owner's call (scope, money, a delete, a\n"
        "cancel), ask the owner one question and park it on_hold with\n"
        'waiting_on: "owner: <the question?>". Owner orders and their label are the owner\'s.\n'
        "FLEET-AGENT-CONDUCT-STANDARD, 'Work what you find; never defer it'.",
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    sys.exit(main())
